    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string dummy;
    cin >> dummy; // s.NextTerm()

    int m;
    cin >> m; // s.NextInt()

    // Consume the rest of the line after m, then read the next line for the array
    string line;
    getline(cin, line); // consume endline after m
    getline(cin, line); // read the line containing gs

    stringstream ss(line);
    vector<int> gs;
    int x;
    while (ss >> x) {
        gs.push_back(x);
    }

    long long b = 0; // use long long to prevent potential overflow if sums are large
    int res = 0;

    for (int i = 0; i < gs.size(); i++) {
        if (b + gs[i] > m) {
            res++;
            b = gs[i];
        } else {
            b += gs[i];
        }
    }

    if (b > 0) {
        res++;
    }

    cout << res << "\n";

    return 0;
}

